N = "3-3"
F = 'font-family="Segoe UI, Arial, sans-serif"'


def titulo():
    return t("Federalism in practice", "El federalismo en la práctica")


def svg_niveles():
    aria = t("Five stacked levels of government for a person who lives in Chicago. Federal: the United States government. State: Illinois. County: Cook County. City: Chicago. Special districts: the school district and others. A bracket shows that only the federal and state levels appear in the U.S. Constitution; the county, the city, and the districts are created by the state.",
             "Cinco niveles de gobierno apilados para una persona que vive en Chicago. Federal: el gobierno de los Estados Unidos. Estatal: Illinois. Condado: el condado de Cook. Ciudad: Chicago. Distritos especiales: el distrito escolar y otros. Una llave indica que solo los niveles federal y estatal aparecen en la Constitución de los Estados Unidos; el condado, la ciudad y los distritos los crea el estado.")
    niv = [(t("Federal", "Federal"), t("United States government", "Gobierno de los Estados Unidos"), "#283593"), (t("State", "Estatal"), t("State of Illinois", "Estado de Illinois"), "#3949ab"),
           (t("County", "Condado"), t("Cook County", "Condado de Cook"), "#7a4a2e"), (t("City", "Ciudad"), t("City of Chicago", "Ciudad de Chicago"), "#965c3a"), (t("Special district", "Distrito especial"), t("School district and others", "Distrito escolar y otros"), "#b07a55")]
    s = [f'<svg class="diagrama" style="max-width:700px" viewBox="0 0 700 330" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">']
    for i, (n, d, c) in enumerate(niv):
        y, w = 14 + i * 62, 440 - i * 40
        x = 30 + i * 20
        s.append(f'<rect x="{x}" y="{y}" width="{w}" height="52" rx="10" fill="{c}"/><text x="{x + 16}" y="{y + 22}" {F} font-size="16" font-weight="700" fill="#fff">{n}</text><text x="{x + 16}" y="{y + 42}" {F} font-size="14" fill="#fff">{d}</text>')
    s.append('<path d="M490 16 h14 v112 h-14" fill="none" stroke="#283593" stroke-width="3"/>')
    s.append(f'<text x="514" y="62" {F} font-size="14" font-weight="700" fill="#283593">{t("In the U.S.", "En la Constitución")}</text><text x="514" y="80" {F} font-size="14" font-weight="700" fill="#283593">{t("Constitution", "de los EE. UU.")}</text>')
    s.append('<path d="M490 140 h14 v174 h-14" fill="none" stroke="#7a4a2e" stroke-width="3"/>')
    s.append(f'<text x="514" y="220" {F} font-size="14" font-weight="700" fill="#7a4a2e">{t("Created by", "Los crea")}</text><text x="514" y="238" {F} font-size="14" font-weight="700" fill="#7a4a2e">{t("the state", "el estado")}</text>')
    s.append("</svg>")
    return "".join(s)


def leccion():
    P = C.Practicas()
    sup = documento(t("Two clauses that pull in opposite directions", "Dos cláusulas que tiran en direcciones contrarias"),
        [(t("Document", "Documento"), t("U.S. Constitution, Article VI (1787) and the Tenth Amendment (1791)", "Constitución de los Estados Unidos, Artículo VI (1787) y Décima Enmienda (1791)")), (t("Kind of source", "Tipo de fuente"), t("Primary · founding document; the English text is the legal one", "Primaria · documento fundacional; el texto en inglés es el legal"))],
        [(t("The supremacy clause · Article VI", "La cláusula de supremacía · Artículo VI"),
          ["This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding."],
          ["Esta Constitución, y las leyes de los Estados Unidos que se dicten con arreglo a ella, y todos los tratados celebrados o que se celebren bajo la autoridad de los Estados Unidos, serán la ley suprema del país; y los jueces de cada estado quedarán obligados por ella, sin que obste nada en contrario en la constitución o las leyes de cualquier estado."]),
         (t("The Tenth Amendment · 1791", "La Décima Enmienda · 1791"),
          ["The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people."],
          ["Los poderes que la Constitución no delega en los Estados Unidos, ni prohíbe a los estados, quedan reservados a los estados respectivamente, o al pueblo."])])
    s1 = f"""<p>{t("American federalism rests on two short sentences that point in different directions. Understanding the tension between them is understanding the whole topic.", "El federalismo estadounidense descansa en dos frases cortas que apuntan hacia lados distintos. Entender la tensión entre ellas es entender el tema entero.")}</p>
{sup}
{C.tabla(t("What each clause does", "Qué hace cada cláusula"), [t("Clause", "Cláusula"), t("What it does", "Qué hace"), t("The detail to notice", "El detalle que hay que ver")],
  [[t("Supremacy (Art. VI)", "Supremacía (art. VI)"), t("When a valid federal law and a state law clash head-on, the federal law wins.", "Cuando una ley federal válida y una ley estatal chocan de frente, gana la federal."), t("“Made in Pursuance thereof”: a federal law that goes beyond the Union’s powers is not supreme, because it is not valid.", "«Que se dicten con arreglo a ella»: una ley federal que exceda los poderes de la Unión no es suprema, porque no es válida.")],
   [t("Tenth Amendment", "Décima Enmienda"), t("Sets the default rule: if a subject was not given to the Union, it belongs to the states (or the people).", "Fija la regla por defecto: si una materia no se le entregó a la Unión, es de los estados (o del pueblo)."), t("It is one of the amendments the Anti-Federalists demanded: the written answer to Brutus’s fear (Lesson 3.2).", "Es una de las enmiendas que exigieron los antifederalistas: la respuesta escrita al miedo de Bruto (Lección 3.2).")]])}
{C.caja("tip", t("How they fit together", "Cómo encajan"), "<p>" + t("The Tenth Amendment says who is in charge by default: the states, except in what was delegated. The supremacy clause says who wins when there is a clash: the Union, as long as it acts within what was delegated. They do not contradict each other. <strong>Almost every real argument is about where exactly the border of “what was delegated” lies.</strong>", "La Décima Enmienda dice quién manda por defecto: los estados, salvo en lo delegado. La cláusula de supremacía dice quién gana cuando hay choque: la Unión, siempre que actúe dentro de lo delegado. No se contradicen. <strong>Casi toda la discusión real es sobre dónde está exactamente la frontera de «lo delegado».</strong>") + "</p>")}"""

    s2 = f"""{C.tabla(t("The three kinds of powers", "Los tres tipos de competencia"), [t("Kind", "Tipo"), t("Who uses it", "Quién la ejerce"), t("Where it comes from", "De dónde sale"), t("Examples", "Ejemplos")],
  [[t("Delegated (federal)", "Delegada (federal)"), t("Only the national government", "Solo la Unión"), t("Named in the Constitution, mostly in Article I, Section 8", "Está nombrada en la Constitución, sobre todo en el Artículo I, sección 8"), t("Printing money, declaring war, post offices, trade between states and with other countries, naturalization", "Emitir moneda, declarar la guerra, correos, comercio entre estados y con otros países, naturalización")],
   [t("Reserved (state)", "Reservada (estatal)"), t("Only the states", "Solo los estados"), t("Not delegated and not forbidden: the Tenth Amendment leaves it to the states", "No está delegada ni prohibida: la Décima Enmienda la deja en los estados"), t("Public schools, driver’s licenses, marriage laws, professional licenses, setting up local governments, running elections", "Escuelas públicas, licencias de conducir, leyes de matrimonio, licencias profesionales, crear gobiernos locales, organizar elecciones")],
   [t("Concurrent (shared)", "Concurrente (compartida)"), t("Both levels at once", "Los dos niveles a la vez"), t("Neither has it alone; each uses it in its own sphere", "Ninguno la tiene en exclusiva; cada uno la ejerce en su ámbito"), t("Collecting taxes, borrowing money, setting up courts, making and enforcing laws", "Cobrar impuestos, pedir préstamos, crear tribunales, hacer y hacer cumplir leyes")]])}
{C.caja("tip", t("The question that settles almost every case", "La pregunta que resuelve casi todos los casos"), "<p>" + t("Is this subject named in the Constitution as a power of the Union? If it is, it is federal. If it is not, check whether both levels actually use it: if both, it is concurrent; if only the states, it is reserved. Education, licenses, and marriage are not mentioned in the document, and that is why they are state matters.", "¿Aparece esta materia nombrada en la Constitución como competencia de la Unión? Si aparece, es federal. Si no aparece, mire si los dos niveles la ejercen de hecho: si los dos, es concurrente; si solo los estados, es reservada. La educación, las licencias y el matrimonio no se mencionan en el documento, y por eso son estatales.") + "</p>")}
{P(t("Practice 1 · Whose job is it?", "Práctica 1 · ¿A quién le toca?"), t("Who issues your driver’s license?", "¿Quién expide la licencia de conducir?"), [t("The federal government", "El gobierno federal"), t("The state", "El estado"), t("Both", "Los dos")], 1,
   {0: t("Is driving named among Congress’s powers?", "¿Aparece la conducción entre los poderes del Congreso?"), 2: t("Only one level issues it.", "Solo un nivel la expide.")}, t("A reserved power: in Illinois, the Secretary of State issues it.", "Una competencia reservada: en Illinois la expide la Secretaría de Estado."))}
{P(t("Practice 2 · Whose job is it?", "Práctica 2 · ¿A quién le toca?"), t("Who can collect income taxes?", "¿Quién puede cobrar impuestos sobre la renta?"), [t("Only the federal government", "Solo el gobierno federal"), t("Only the states", "Solo los estados"), t("Both", "Los dos")], 2,
   {0: t("Illinois also has an income tax.", "Illinois también tiene un impuesto sobre la renta."), 1: t("The federal government collects one too.", "El gobierno federal también cobra uno.")}, t("Taxing is a concurrent power.", "Cobrar impuestos es una competencia concurrente."))}
{C.enlace(N, t("whose-job", "a-quien"), t("Whose job is it?", "¿A quién le toca?"), t("Twenty-one real powers to sort into federal, state, or shared.", "Veintiuna competencias reales para clasificar en federal, estatal o compartida."))}"""

    s3 = f"""<p>{t("Federalism is not an abstraction: it is the reason some errands are done in one office and others in another. This is how the levels stack up for someone who lives in Chicago.", "El federalismo no es una abstracción: es la razón de que unos trámites se hagan en una oficina y otros en otra. Así se apilan los niveles para alguien que vive en Chicago.")}</p>
{svg_niveles()}
{C.tabla(t("Who does what, for someone who lives in Chicago", "Quién hace qué, para alguien que vive en Chicago"), [t("Level", "Nivel"), t("Some of its jobs", "Algunas de sus funciones")],
  [[t("Federal · United States", "Federal · Estados Unidos"), t("Money, defense, the mail, immigration, trade between states. The President, Congress, and the federal courts.", "Moneda, defensa, correos, inmigración, comercio entre estados. La presidencia, el Congreso y los tribunales federales.")],
   [t("State · Illinois", "Estatal · Illinois"), t("Education, driver’s and professional licenses, criminal law, family law. A governor, a General Assembly with two chambers, and its own courts: the state repeats the three-branch structure.", "Educación, licencias de conducir y profesionales, código penal, derecho de familia. Un gobernador, una Asamblea General de dos cámaras y sus propios tribunales: el estado repite la estructura de tres poderes.")],
   [t("County · Cook", "Condado · Cook"), t("Property records, trial courts, public health, the county jail.", "Registros de la propiedad, tribunales de primera instancia, salud pública, la cárcel del condado.")],
   [t("City · Chicago", "Ciudad · Chicago"), t("The mayor and the City Council (the aldermen of Lesson 1.3). Police, fire department, garbage pickup, business licenses, local ordinances.", "El alcalde y el Concejo Municipal (los concejales de la Lección 1.3). Policía, bomberos, recogida de basura, licencias de negocio, ordenanzas locales.")],
   [t("Special districts", "Distritos especiales"), t("The school district and other districts with a single purpose (parks, water). They exist because the state creates them.", "El distrito escolar y otros distritos con un solo fin (parques, agua). Existen porque el estado los crea.")]])}
{C.caja("ojo", t("The jump that does not exist", "El salto que no existe"), "<p>" + t("Counties, cities, and school districts do not appear in the U.S. Constitution. They exist because the state creates them, and the state can change them. So talking about “three levels of government” is a handy simplification: in fact there are <strong>two constitutional levels</strong>, the Union and the states, and everything else is created by the states.", "Los condados, las ciudades y los distritos escolares no aparecen en la Constitución federal. Existen porque el estado los crea, y el estado puede modificarlos. Por eso hablar de «tres niveles de gobierno» es una simplificación cómoda: en realidad hay <strong>dos niveles constitucionales</strong>, la Unión y los estados, y todo lo demás es creación estatal.") + "</p>")}"""

    s4 = f"""<p>{t("Conflicts between the levels do not all have the same shape. These three are different from each other, and recognizing the shape is what lets you analyze them.", "Los conflictos entre los niveles no tienen todos la misma forma. Estos tres son distintos entre sí, y reconocer la forma es lo que permite analizarlos.")}</p>
{C.tabla(t("Three shapes of conflict", "Tres formas de conflicto"), [t("Shape", "Forma"), t("Example", "Ejemplo"), t("What is going on", "Qué está en juego")],
  [[t("1 · A federal floor", "1 · Un suelo federal"), t("The minimum wage. The federal minimum is $7.25 an hour; Illinois set its own at $15 in 2025.", "El salario mínimo. El mínimo federal es de 7.25 dólares por hora; Illinois fijó el suyo en 15 dólares en 2025."), t("No real conflict: the federal law sets a floor and the state builds above it. A concurrent power working as intended. Many people read it as a clash, and it is not one.", "No hay conflicto real: la ley federal marca un suelo y el estado construye encima. Una competencia concurrente funcionando como está previsto. Mucha gente lo lee como un choque, y no lo es.")],
   [t("2 · Strings attached to money", "2 · Condiciones para recibir fondos"), t("Highways and schools. The Union cannot order a state to pass a law on a reserved subject, but it can offer federal money if the state adopts a rule. (In 1984, highway funds were tied to a drinking age of 21.)", "Las carreteras y las escuelas. La Unión no puede ordenar a un estado que legisle en una materia reservada, pero sí puede ofrecerle dinero federal si adopta una norma. (En 1984, los fondos de carreteras se condicionaron a una edad mínima de 21 años para beber)."), t("Formally there is no supremacy, because nobody imposes anything: there is a deal, and the state can say no and lose the money. In practice people argue about how much financial pressure turns an offer into an order.", "Formalmente no hay supremacía, porque nadie impone nada: hay un acuerdo, y el estado puede decir que no y quedarse sin el dinero. En la práctica se discute cuánta presión económica convierte una oferta en una orden.")],
   [t("3 · A head-on clash", "3 · Choque frontal"), t("Cannabis. Illinois has allowed licensed adult sales since 2020. Federal law still does not allow recreational cannabis (in 2026 only state-licensed medical cannabis and FDA-approved products were moved to a less strict category).", "El cannabis. Illinois permite desde 2020 la venta con licencia a adultos. La ley federal sigue sin permitir el cannabis recreativo (en 2026 solo el cannabis medicinal con licencia estatal y los productos aprobados por la FDA pasaron a una categoría menos estricta)."), t("Supremacy against reserved powers, in pure form. The federal law is still in force and a state cannot repeal it; what has happened is that the Union has mostly chosen not to prosecute activity a state allows. A practical truce, not a legal solution.", "Supremacía frente a poderes reservados, en estado puro. La ley federal sigue vigente y un estado no puede derogarla; lo que ha ocurrido es que la Unión ha optado en general por no perseguir la actividad que un estado autoriza. Una tregua de hecho, no una solución jurídica.")]])}
{C.caja("tip", t("The method, in three questions", "El método, en tres preguntas"), "<p>" + t("For any conflict you read about in the news: (1) Is the subject delegated to the Union, reserved to the states, or shared? (2) Are the two laws incompatible, or can they live together? (3) If they are incompatible, is the Union acting within what the Constitution delegates? With those three answers you know which principle is at stake.", "Ante cualquier conflicto que lea en la prensa: (1) ¿La materia está delegada a la Unión, reservada a los estados o es compartida? (2) ¿Las dos normas son incompatibles o pueden convivir? (3) Si son incompatibles, ¿actúa la Unión dentro de lo que la Constitución le delega? Con esas tres respuestas ya sabe qué principio está en juego.") + "</p>")}
{P(t("Practice 3 · Analyze the conflict", "Práctica 3 · Analice el conflicto"), t("Can a federal law always override a state law?", "¿Puede una ley federal imponerse siempre sobre una estatal?"),
   [t("Yes, always, with no exception", "Sí, siempre, sin excepción"), t("No, the state law always wins in its own territory", "No, la estatal siempre prevalece en su territorio"), t("Only if the federal law was made within the powers the Constitution delegates", "Solo si la ley federal se dictó dentro de las competencias que la Constitución delega")], 2,
   {0: t("Read “in Pursuance thereof” again.", "Vuelva a leer «con arreglo a ella»."), 1: t("That ignores the supremacy clause.", "Eso ignora la cláusula de supremacía.")}, t("Supremacy applies only to laws “made in Pursuance” of the Constitution.", "La supremacía solo vale para las leyes dictadas «con arreglo» a la Constitución."))}
{C.enlace(N, t("conflicts", "conflictos"), t("Analyze the conflict", "Analice el conflicto"), t("Recognize the shape of each conflict between levels.", "Reconozca la forma de cada conflicto entre niveles."))}"""

    G = lambda *a: C.ged_item(P, *a)
