# ---------------------------------------------------------------- la práctica
def casos_quien():
    G = [t("Federal (delegated)", "Federal (delegada)"), t("State (reserved)", "Estatal (reservada)"), t("Both (concurrent)", "Los dos (concurrente)")]
    PF = t("Is it named in the Constitution as a power of Congress or the President?", "¿Está nombrada en la Constitución como competencia del Congreso o del presidente?")
    PE = t("It is not in the Constitution, and only the states do it.", "No está en la Constitución, y solo la ejercen los estados.")
    PC = t("Do both the national government and the states do this?", "¿Lo hacen tanto el gobierno nacional como los estados?")
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("Whose job is each power?", "¿A quién le toca cada competencia?"), "grupos": G, "etiqueta": t("This power is…", "Esta competencia es…"),
                "piezas": [{"t": a, "v": v, "pista": [PF, PE, PC][v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("Printing money", "Emitir moneda"), 0), (t("Issuing driver’s licenses", "Expedir licencias de conducir"), 1), (t("Collecting taxes", "Cobrar impuestos"), 2), (t("Declaring war", "Declarar la guerra"), 0),
                                      (t("Setting marriage laws", "Fijar las leyes del matrimonio"), 1), (t("Borrowing money", "Pedir préstamos"), 2), (t("Running the post office", "Administrar el correo"), 0)]),
        caso(t("Set 2", "Serie 2"), [(t("Making treaties with other countries", "Celebrar tratados con otros países"), 0), (t("Running public schools", "Organizar las escuelas públicas"), 1), (t("Setting up courts", "Crear tribunales"), 2), (t("Regulating trade between states", "Regular el comercio entre estados"), 0),
                                      (t("Licensing nurses and barbers", "Dar licencias a enfermeras y barberos"), 1), (t("Making and enforcing laws", "Hacer y hacer cumplir leyes"), 2), (t("Deciding who can become a citizen (naturalization)", "Decidir quién puede hacerse ciudadano (naturalización)"), 0)]),
        caso(t("Set 3", "Serie 3"), [(t("Keeping an army and a navy", "Mantener un ejército y una marina"), 0), (t("Creating counties and cities", "Crear condados y ciudades"), 1), (t("Taking private land for public use, with payment", "Expropiar terrenos para uso público, pagándolos"), 2), (t("Granting patents and copyrights", "Conceder patentes y derechos de autor"), 0),
                                      (t("Running elections and counting ballots", "Organizar elecciones y contar los votos"), 1), (t("Chartering banks", "Autorizar bancos"), 2), (t("Regulating trade within a single state", "Regular el comercio dentro de un solo estado"), 1)]),
    ]


def banco_conflicto():
    S = [t("A federal floor (no real conflict)", "Un suelo federal (sin conflicto real)"), t("Strings attached to money", "Condiciones para recibir fondos"), t("A head-on clash", "Un choque frontal")]
    datos = [
        (t("Federal law requires a 40-hour work week before overtime; a state requires overtime after 8 hours in a single day.", "La ley federal exige horas extra después de 40 horas semanales; un estado las exige después de 8 horas en un mismo día."), 0, t("Employers can obey both: the state adds protection on top of the federal floor.", "Los empleadores pueden cumplir las dos: el estado añade protección encima del suelo federal.")),
        (t("The federal government offers education grants only to states that test students every year.", "El gobierno federal ofrece fondos educativos solo a los estados que evalúen a sus estudiantes cada año."), 1, t("An offer the state may refuse, at the cost of the money.", "Una oferta que el estado puede rechazar, a costa del dinero.")),
        (t("A state law allows something that a valid federal law forbids.", "Una ley estatal permite algo que una ley federal válida prohíbe."), 2, t("The two rules cannot both be followed; supremacy is at stake.", "No se pueden cumplir las dos normas; está en juego la supremacía.")),
        (t("A state sets stricter clean-air rules for cars than the federal rules.", "Un estado fija normas de aire limpio para los autos más estrictas que las federales."), 0, t("A stricter rule on top of a federal minimum, where the law allows it.", "Una norma más estricta encima de un mínimo federal, donde la ley lo permite.")),
        (t("Highway funds are cut for states that do not set the drinking age at 21.", "Se recortan los fondos de carreteras a los estados que no fijen en 21 años la edad para beber."), 1, t("The 1984 law: money with conditions.", "La ley de 1984: dinero con condiciones.")),
        (t("A state passes a law saying a federal law does not apply inside its borders.", "Un estado aprueba una ley que dice que una ley federal no se aplica dentro de sus fronteras."), 2, t("A head-on clash; under the supremacy clause, a state cannot cancel a valid federal law.", "Un choque frontal; por la cláusula de supremacía, un estado no puede anular una ley federal válida.")),
    ]
    out = [{"enun": t("What shape does this conflict have?", "¿Qué forma tiene este conflicto?") + "<br><strong>" + s + "</strong>", "ops": S, "ok": k, "exp": f"<strong>{S[k]}.</strong> " + e, "enOrden": True} for s, k, e in datos]
    otros = [
        (t("A subject is not in the Constitution and is not forbidden to the states. Whose is it?", "Una materia no está en la Constitución ni está prohibida a los estados. ¿De quién es?"), [t("The states’, under the Tenth Amendment", "De los estados, por la Décima Enmienda"), t("The Union’s, under the supremacy clause", "De la Unión, por la cláusula de supremacía"), t("Nobody’s", "De nadie")], t("The default rule.", "La regla por defecto.")),
        (t("Who wins when a valid federal law and a state law directly contradict each other?", "¿Quién gana cuando una ley federal válida y una ley estatal se contradicen directamente?"), [t("The federal law", "La ley federal"), t("The state law, inside the state", "La ley estatal, dentro del estado"), t("Whichever is newer", "La más reciente")], t("The supremacy clause.", "La cláusula de supremacía.")),
    ]
    out += [{"enun": "<strong>" + s + "</strong>", "ops": ops, "ok": 0, "exp": e} for s, ops, e in otros]
    return out


def practica():
    A = {"en": ["whose-job", "conflicts"], "es": ["a-quien", "conflictos"]}[C.L]
    mods = [
        (A[0], t("Whose job is it?", "¿A quién le toca?"), C.clasifica("m1", t("Sort each power. Ask: is it named in the Constitution for the Union? If not, do both levels do it, or only the states? If something is not right, the powers marked in yellow get a hint.", "Clasifique cada competencia. Pregúntese: ¿está nombrada en la Constitución para la Unión? Si no, ¿la ejercen los dos niveles o solo los estados? Si algo no está bien, las competencias marcadas en amarillo reciben una pista."))),
        (A[1], t("Analyze the conflict", "Analice el conflicto"), C.om("m2", t("Can both rules be followed at once (a floor)? Is it an offer of money (conditions)? Or do they say opposite things (a clash)?", "¿Se pueden cumplir las dos normas a la vez (un suelo)? ¿Es una oferta de dinero (condiciones)? ¿O dicen cosas opuestas (un choque)?"))),
    ]
    js = C.js_datos("QUI", casos_quien()) + C.js_datos("CON", banco_conflicto()) + 'creaClasifica("m1", QUI);\ncreaBanco("m2", CON);\n'
    return C.pagina_practica(N, titulo(), t("Two activities · the order of the exercises changes every time · two tries in each one", "Dos actividades · el orden de los ejercicios cambia cada vez · dos intentos en cada uno"), mods, js)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
